// 10WAVEåˆ¶è¦‡æ™‚ã®åˆè¨ˆã¯æ—§ä»•æ§˜(ä¸€å¾‹10XPÃ—10WAVE=100)ã¨å¤‰ã‚ã‚‰ãªã„
const WAVE_XP_TABLE = [4, 5, 6, 7, 8, 10, 12, 14, 16, 18];
const waveXpGain = (waveNum, mult) => Math.round((WAVE_XP_TABLE[waveNum - 1] || 0) * mult);
