  // ãƒã‚¹ãƒ¢ãƒ³ã®è©³ç´°ã‹ã‚‰ã„ã¤ã§ã‚‚ä½¿ãˆã‚‹ã€‚å¾Œã‹ã‚‰è¶³ã—ãŸé …ç›®ãªã®ã§ã€æŒã£ã¦ã„ãªã„æ—¢å­˜ãƒ‡ãƒ¼ã‚¿ã¯0
