const getMasuColors = (masu) => (masu && masu.colors) || (masu && masu.color ? [masu.color] : []);
// ãƒã‚¹ãƒ¢ãƒ³ã®å€‹ä½“åŸºç¤å€¤ã‚’æ–°æ—§ã©ã¡ã‚‰ã®ä¿å­˜å½¢å¼ã‹ã‚‰ã‚‚è§£æ±ºã™ã‚‹ã€‚
