  // ä¾›ãƒ¢ãƒ³æ™‚ã®åˆæµãƒœãƒ¼ãƒŠã‚¹ã«ã‚‚ã€é€šå¸¸å¼·åŒ–ã¨åŒã˜ãè¶…è¶Šã§ä¸Šã’ãŸåŸºç¤å€¤ã‚’100%ä¹—ã›ã‚‹ã€‚
  // transcendStatPoints ã¯å®Ÿéš›ã®å¢—åŠ å€¤ãªã®ã§å€ç‡æ›ç®—ã›ãšã€ãã®ã¾ã¾1åº¦ã ã‘åŠ ç®—ã™ã‚‹ã€‚
  const tsp = normalizeTranscendStatPoints(masu?.transcendStatPoints);
