const UNKNOWN_LINEAGE = Object.freeze({ id:'unknown', name:'ï¼Ÿï¼Ÿï¼Ÿ', rare:true });
const lineageCatalog = () => (typeof MONSTER_LINEAGES !== 'undefined' && MONSTER_LINEAGES) || {};
