const EXACT_DYE_MASKS = Object.freeze({ Mocchi:MOCCHI_DYE_MASK, Yaobikuni:YAOBIKUNI_DYE_MASK, Plant:PLANT_DYE_MASK, Eiki:EIKI_DYE_MASK, Pandora:PANDORA_DYE_MASK });
const EXACT_DYE_MASK_PLACEMENT = Object.freeze({ scaleX: 1, scaleY: 1, x: 0, y: 0 });
// ã‚¿ãƒƒãƒå¼ãƒã‚¹ã‚¯ã‚¨ãƒ‡ã‚£ã‚¿ã®å¯¾è±¡ã¯ ALL_PLAYER_MONSTERS ã‹ã‚‰å®Ÿè¡Œæ™‚ã«ç”Ÿæˆã™ã‚‹ã€‚
// ãƒ¢ãƒ³ã‚¹ã‚¿ãƒ¼åãƒ»ç”»åƒURLã‚’Debugç”¨ã«è¤‡è£½ã›ãšã€æ–°è¦ãƒ™ãƒ¼ã‚¹ãƒ¢ãƒ³ã‚‚è‡ªå‹•çš„ã«å€™è£œã¸åŠ ã‚ã‚‹ã€‚
// ãƒ‘ãƒ³ãƒ‰ãƒ©ã¯æ­£å¼ãª5è‰²ãƒã‚¹ã‚¯ã‚’ä½¿ã†ã€‚èµ¤=â‘ ã€ç·‘=â‘¡ã€é’=â‘¢ã€é»„=â‘£ã€ãƒã‚¼ãƒ³ã‚¿=â‘¤ã€‚
