          // å›²ã¾ã‚Œã¦ã„ã‚‹ãŸã‚å¤šæ•°æ±ºã®å¹³æ»‘åŒ–ã§å¡—ã‚Šæ½°ã•ã‚Œã¦æ¶ˆãˆã¦ã—ã¾ã†ã“ã¨ãŒã‚ã‚‹ã€‚
          // ãã®ãŸã‚å…ƒã®åˆ¤å®š(1ãƒ‘ã‚¹ç›®ã®çµæœ)ã‚’å¹³æ»‘åŒ–å¾Œã«ä¸Šæ›¸ãå¾©å…ƒã—ã€ç¢ºå®Ÿã«æ®‹ã™
          for (let i = 0; i < w*h; i++) {
            const orig = grid[i];
            if (orig < 0) continue;
            const def = regionDefs[orig];
            if (def && typeof def === 'object' && (def.noEdgeGuard || def.posBbox)) smoothed[i] = orig;
          }
